    uint8_t* escaped_char)
{
  char text[4] = {0, 0, 0, 0};

   text[0] = '\\';
   text[1] = RE_YY_INPUT(yyscanner);

  if (text[1] == EOF)
     return 0;

   if (text[1] == 'x')
